          if (!match)
            continue;
          const [, column, operator, bound] = match;
          const ceiling = operator === ">=" ? Number(bound) - 0.01 : Number(bound);
          const key = `${rule.tableName}.${column}`;
          ceilings.set(key, Math.min(ceilings.get(key) ?? ceiling, ceiling));
